const input = $input.first().json;
const p = input.body || input;
const tz = 'America/Mexico_City';
const now = new Date();
const todayCDMX = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const requestId = String(p.source_message_id || p.request_id || p.message_id || p.id || `ci-${Date.now()}`);
const text = String(p.text || p.message || p.body || '').slice(0, 1200);
const history = Array.isArray(p.history) ? p.history.slice(-12) : [];
const accountContext = p.account_context && typeof p.account_context === 'object' ? p.account_context : null;
const conversationContext = p.conversation_context && typeof p.conversation_context === 'object' ? p.conversation_context : null;
const contextualText = String(
  conversationContext?.contextualText
    || [conversationContext?.previousQuestion, conversationContext?.currentReply].filter(Boolean).join('\nRespuesta: ')
    || text
).slice(0, 1200);

const contact = {
  wa_number: p.wa_number || p.waNumber || p.account_wa_number || null,
  contact_number: p.contact_number || p.contactNumber || p.from || p.phone || null,
  name: p.contact_name || p.contactName || p.name || null,
  espo_id: p.espo_id || p.espoId || null,
  role: p.role || p.contact?.role || null
};

const accountInput = accountContext || p.account || {};
const projects = Array.isArray(accountContext?.projects) ? accountContext.projects : [];
const primaryProject = projects.find(project => project?.isDefault) || projects[0] || null;
const account = {
  name: accountInput.name || p.account_name || p.company || null,
  project: accountInput.project || primaryProject?.projectKey || p.project || p.project_name || null,
  project_slug: accountInput.project_slug || primaryProject?.projectKey || p.project_slug || null
};

const inputMode = p.input_mode || 'direct';
const ownerAssistance = (inputMode === 'owner_assistance' || p.owner_assistance) ? {
  failure_id: p.failure_id || p.owner_assistance?.failure_id || null,
  owner_instruction: p.owner_instruction || p.owner_assistance?.owner_instruction || p.text || '',
  original_request: p.original_request || p.owner_assistance?.original_request || '',
  original_contact_number: contact.contact_number,
  original_contact_name: contact.name,
  source_message_id: p.source_message_id || p.owner_assistance?.source_message_id || requestId,
  owner_message_id: p.owner_message_id || p.owner_assistance?.owner_message_id || null
} : null;

const identityStatus = contact.espo_id ? 'known' : (contact.contact_number ? 'candidate' : 'unknown');

const context = {
  source: p.source || 'unknown',
  request_id: requestId,
  channel: p.channel || 'whatsapp',
  text,
  stage: p.stage || 'desconocido',
  history,
  contact,
  account,
  account_key: accountContext?.accountKey || p.account_key || null,
  account_context: accountContext,
  conversation_context: conversationContext,
  contextual_text: contextualText,
  project_slug: account.project_slug || account.project || 'ia360',
  dry_run: p.dry_run === undefined ? true : Boolean(p.dry_run),
  today_cdmx: todayCDMX,
  identity_status_seed: identityStatus,
  input_mode: inputMode,
  failure_id: p.failure_id || null,
  owner_assistance: ownerAssistance,
  message_type: p.message_type || 'text',
  structured: p.structured || null,
  contract_version: p.contract_version || 2,
  architecture_note: 'Draft agentic workflow: identity -> classification -> tools/RAG -> response contract. No sends or writes without owner confirmation.'
};

return [{ json: { ...context, agent_input: JSON.stringify(context, null, 2) } }];

const j = $input.first().json;
const seed = {
  identity_status: j.identity_status_seed || 'unknown',
  contact_number_present: !!(j.contact && j.contact.contact_number),
  espo_id_present: !!(j.contact && j.contact.espo_id),
  source: j.source,
  note: 'Draft snapshot only. Real lookup/write remains pending for ForgeChat/EspoCRM subworkflow.'
};
return [{ json: { ...j, identity_snapshot: seed } }];

const base = ($('Prepare RAG Pinecone Dry Run').first()?.json) || $('Lookup IA360 Memory').first().json || $('Identity Snapshot').first().json || $('Normalize WhatsApp Context').first().json;
const memoryContext = base.memory_context || null;
const memorySeen = Boolean(memoryContext && (memoryContext.facts_count > 0 || memoryContext.events_count > 0 || memoryContext.memory_rows > 0));
const signalClassification = base.signal_classification || null;
const ragContext = base.rag_context || null;
const rawItem = $input.first().json;
const agentErrorCode = typeof rawItem?.error === 'string' && rawItem.error.trim() ? 'AGENT_PROVIDER_UNAVAILABLE' : null;

let candidate = rawItem.output ?? rawItem.text ?? rawItem;
if (typeof candidate === 'string') {
  const trimmed = candidate.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { candidate = JSON.parse(trimmed); } catch (e) { candidate = { reply: trimmed }; }
}
if (!candidate || typeof candidate !== 'object') candidate = {};

const allowedIntents = new Set(['book','ask_pain','provide_info','optout','smalltalk','other','list_bookings']);
const allowedActions = new Set(['offer_slots','book','cancel','reschedule','list_bookings','advance_pain','nurture','optout','reply_to_contact','none']);
const allowedAudiences = new Set(['owner', 'contact']);

const audience = allowedAudiences.has(candidate.response_audience)
  ? candidate.response_audience
  : (base.input_mode === 'owner_assistance' ? 'owner' : 'contact');

const ci = candidate.contact_intelligence && typeof candidate.contact_intelligence === 'object' ? candidate.contact_intelligence : {};
const toolsUsed = Array.isArray(ci.tools_used) ? [...ci.tools_used] : [];
if (memorySeen && !toolsUsed.includes('ia360_memory_lookup')) toolsUsed.push('ia360_memory_lookup');
if (signalClassification && !toolsUsed.includes('ia360_signal_classifier_gpt_5_5')) toolsUsed.push('ia360_signal_classifier_gpt_5_5');
if (ragContext && !toolsUsed.includes('ia360_hybrid_rag')) toolsUsed.push('ia360_hybrid_rag');

const text = String(base.text || '').trim();
const lower = text.toLowerCase();

function cleanText(value, max = 240) {
  return String(value || '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

let reply = String(candidate.reply || (base.input_mode === 'owner_assistance' ? 'Entendido Alek, procesando la solicitud del contacto.' : 'Te leo. Para cuidarlo bien, lo dejo como revisión de Alek antes de responder.'));
let intent = allowedIntents.has(candidate.intent) ? candidate.intent : 'other';
let action = allowedActions.has(candidate.action) ? candidate.action : 'none';

const confidence = typeof ci.confidence === 'number' ? Math.max(0, Math.min(1, ci.confidence)) : (signalClassification?.confidence || 0.85);

const auditContact = {
  masked_contact_number: base.contact?.contact_number || null,
  name: cleanText(base.contact?.name || '', 120) || null,
  role: cleanText(base.contact?.role || '', 120) || null,
  espo_contact_id: base.contact?.espo_id || null,
};

const out = {
  reply: reply.slice(0, 600),
  intent,
  date: /^\d{4}-\d{2}-\d{2}$/.test(String(candidate.date || '')) ? String(candidate.date) : null,
  action,
  response_audience: audience,
  extracted: candidate.extracted && typeof candidate.extracted === 'object' ? candidate.extracted : {},
  input_mode: base.input_mode || 'direct',
  failure_id: base.failure_id || null,
  owner_assistance: base.owner_assistance || null,
  source: 'ia360-contact-intelligence-agent-draft',
  agent_error_code: agentErrorCode,
  account_context: base.account_context || null,
  conversation_context: base.conversation_context || null,
  contextual_text: base.contextual_text || base.text || '',
  contact_intelligence: {
    identity_status: ci.identity_status || base.identity_snapshot?.identity_status || 'unknown',
    route: ci.route || 'human_review',
    stage_signal: ci.stage_signal || base.stage || 'desconocido',
    tools_used: toolsUsed,
    confidence,
    next_best_action: ci.next_best_action || signalClassification?.next_action || 'Auditar en WhatsApp/n8n antes de actuar.',
    human_review_required: ci.human_review_required !== false || Boolean(signalClassification?.owner_review_required),
  },
  dry_run: base.dry_run === undefined ? true : Boolean(base.dry_run),
  requires_human_approval: true,
  memory_context: memoryContext,
  signal_classification: signalClassification,
  rag_context: ragContext,
  audit: {
    request_id: base.request_id,
    channel: base.channel,
    contact: auditContact,
    identity_snapshot: base.identity_snapshot,
    memory_context: memoryContext,
    signal_classification: signalClassification,
    rag_context: ragContext,
  },
};

return [{ json: out }];

