const contactNumber = $fromAI('contact_number', 'Numero de WhatsApp del contacto si esta disponible', 'string');
const espoId = $fromAI('espo_id', 'ID EspoCRM si ya existe', 'string');
return JSON.stringify({ ok: true, mode: 'draft', identity_status: espoId ? 'known' : (contactNumber ? 'candidate' : 'unknown'), contact_number_present: !!contactNumber, espo_id_present: !!espoId, note: 'No escribe datos. En la siguiente iteracion este tool consulta ForgeChat/EspoCRM.' });

const j = $input.first().json;
const baseUrl = String($env.FORGECHAT_API_BASE_URL || 'https://wa.geekstudio.dev').replace(/\/$/, '');
const secret = $env.IA360_DIRECTIVE_SECRET || '';

async function lookupMemory(contact) {
  const guardrails = {
    transcript_returned: false,
    external_send_allowed: false,
    crm_write_executed: false
  };
  if (!secret) {
    return { ok: false, error: 'missing_IA360_DIRECTIVE_SECRET', events: [], facts: [], guardrails };
  }
  if (!contact?.wa_number || !contact?.contact_number) {
    return { ok: false, error: 'missing_contact_keys', events: [], facts: [], guardrails };
  }
  const payload = {
    wa_number: contact.wa_number,
    contact_number: contact.contact_number,
    limit: 8
  };
  if (this?.helpers?.httpRequest) {
    return await this.helpers.httpRequest({
      method: 'POST',
      url: `${baseUrl}/api/internal/ia360-memory/lookup`,
      headers: {
        'content-type': 'application/json',
        'X-IA360-Directive-Secret': secret
      },
      body: payload,
      json: true
    });
  }
  if (typeof fetch !== 'function') {
    return { ok: false, error: 'http_client_unavailable', events: [], facts: [], guardrails };
  }
  const res = await fetch(`${baseUrl}/api/internal/ia360-memory/lookup`, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'X-IA360-Directive-Secret': secret
    },
    body: JSON.stringify(payload)
  });
  const data = await res.json().catch(() => ({}));
  return { ...data, ok: Boolean(data.ok) && res.ok };
}

const memory = await lookupMemory.call(this, j.contact || {});
const memoryFacts = Array.isArray(memory.facts) ? memory.facts.slice(0, 5) : [];
const memoryEvents = Array.isArray(memory.events) ? memory.events.slice(0, 5) : [];
const memorySummary = [
  ...memoryFacts.map(f => ({
    type: 'fact',
    persona: f.persona || null,
    role: f.role || null,
    preference: f.preference || null,
    recurring_pain: f.recurring_pain || null,
    affected_process: f.affected_process || null,
    missing_metric: f.missing_metric || null,
    confidence: f.confidence || null,
    status: f.status || null
  })),
  ...memoryEvents.map(e => ({
    type: 'event',
    area: e.area || null,
    signal_type: e.signal_type || null,
    summary: e.summary || null,
    business_impact: e.business_impact || null,
    missing_data: e.missing_data || null,
    next_action: e.next_action || null,
    owner_review_status: e.owner_review_status || null
  }))
];

const memoryContext = {
  schema: 'ia360_memory_context_for_agent.v1',
  ok: Boolean(memory.ok),
  facts_count: memoryFacts.length,
  events_count: memoryEvents.length,
  summary: memorySummary,
  lookup_error: memory.ok ? null : (memory.error || null),
  guardrails: {
    transcript_returned: false,
    external_send_allowed: false,
    crm_write_executed: false
  }
};

const agentPayload = {
  ...j,
  memory_context: memoryContext,
  instruction: 'Antes de responder, usa memory_context si trae facts o events. No inventes datos. No copies transcript. Si hay señal útil, responde con hallazgo, impacto, dato faltante y siguiente acción. En contact_intelligence.tools_used incluye ia360_memory_lookup cuando este contexto exista.'
};

return [{
  json: {
    ...j,
    memory_context: memoryContext,
    agent_input: JSON.stringify(agentPayload, null, 2)
  }
}];

const base = $('Lookup IA360 Memory').first().json;
const rawItem = $('IA360 Signal Classifier - gpt-5.5').first().json;
const gw = $('Estado Vivo del Contacto').first().json || {};

function cleanText(value, max = 240) {
  return String(value || '')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, '[email]')
    .replace(/\+?\d[\d\s().-]{7,}\d/g, '[phone]')
    .replace(/\b(?:sk|pk|rk|org|proj)-[A-Za-z0-9_-]{16,}\b/g, '[secret]')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

function digits(value) { return String(value || '').replace(/\D/g, ''); }
function maskNumber(value) {
  const s = digits(value);
  return s ? `${s.slice(0, 3)}***${s.slice(-2)}` : '';
}
function slug(value, fallback = 'ia360') {
  const out = String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return out || fallback;
}

function parseClassifier(raw) {
  let candidate = raw.output ?? raw.text ?? raw;
  if (typeof candidate === 'string') {
    const trimmed = candidate.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
    try { candidate = JSON.parse(trimmed); } catch (e) { candidate = {}; }
  }
  if (!candidate || typeof candidate !== 'object') candidate = {};
  const allowed = new Set(['cartera_cobranza_portal', 'taller_garantia_dias_detencion', 'auditoria_licencias_gasto', 'fiscal_opinion_sat_sync', 'no_signal']);
  const primaryArea = allowed.has(candidate.primary_area) ? candidate.primary_area : 'no_signal';
  const confidence = Math.max(0, Math.min(1, Number(candidate.confidence || 0)));
  const ownerReviewRequired = candidate.owner_review_required !== false || confidence < 0.72 || primaryArea === 'no_signal';
  return {
    schema: 'ia360_signal_classifier_result.v1',
    primary_area: primaryArea,
    confidence,
    summary: cleanText(candidate.summary || '', 240) || null,
    missing_data: cleanText(candidate.missing_data || '', 180) || null,
    next_action: cleanText(candidate.next_action || '', 180) || null,
    owner_review_required: ownerReviewRequired,
    model: 'gpt-5.5',
    classification_timestamp: new Date().toISOString(),
  };
}

const classification = parseClassifier(rawItem);
const projectSlug = slug(base.project_slug || base.account?.project_slug || base.account_context?.projectKey || 'ia360');
const activeAccountKey = String(gw.account_key || base.account_key || 'nexus').trim() || 'nexus';
const contactKey = base.contact?.contact_number || base.contact?.wa_number || base.request_id;
const collName = `ia360_${projectSlug}`;

const hybridDocs = [
  ...(base.memory_context?.facts || []).map(f => ({ source: 'memory_fact', text: f.fact_text || f.text })),
  ...(base.memory_context?.events || []).map(e => ({ source: 'memory_event', text: e.event_summary || e.summary })),
].filter(d => Boolean(d.text));

const ragContext = {
  schema: 'ia360_hybrid_rag_context.v1',
  active_account_key: activeAccountKey,
  collection: collName,
  project_slug: projectSlug,
  facts_count: (base.memory_context?.facts || []).length,
  events_count: (base.memory_context?.events || []).length,
  documents_retrieved: hybridDocs.length,
  documents: hybridDocs.slice(0, 10),
  guardrails: {
    no_cross_contact_context: true,
    isolated_by_collection: true,
    fail_closed_urls: true
  }
};

const vivos = (gw.estado_vivo && Array.isArray(gw.estado_vivo.issues)) ? gw.estado_vivo.issues : [];
const planeLive = {
  schema: 'ia360_plane_estado_vivo.v1',
  leido_en_vivo: true,
  nunca_persistido: true,
  scope_ok: gw.scope_ok === true,
  account_key: activeAccountKey,
  proyectos_permitidos: Array.isArray(gw.permitted_projects) ? gw.permitted_projects : [],
  active_project_id: gw.active_project_id || null,
  active_project_identifier: gw.active_project_identifier || null,
  issues_count: vivos.length,
  issues: vivos.slice(0, 25).map(w => ({
    referencia: w.sequence_id ? String(w.sequence_id) : null,
    nombre: w.nombre,
    prioridad: w.priority || null,
  })),
  fuente: 'Plane REST al momento de contestar',
};

const agentPayload = {
  ...base,
  input_mode: base.input_mode || 'direct',
  failure_id: base.failure_id || null,
  owner_assistance: base.owner_assistance || null,
  signal_classification: classification,
  rag_context: ragContext,
  plane_live: planeLive,
  active_project: {
    account_key: activeAccountKey,
    plane_project_id: gw.active_project_id || null,
    plane_identifier: gw.active_project_identifier || null
  },
  instruction: [
    'Usa signal_classification, rag_context y plane_live.',
    'REGLA INVIOLABLE DE SUPERFICIES Y ENLACES:',
    '1. SOLO puedes mencionar URLs que figuren explícitamente en verified_surfaces o en los hechos verificados de rag_context.',
    '2. NUNCA inventes o asumas dominios .com sin verificación.',
    '3. Si el usuario pide un enlace y no existe un enlace verificado en tu contexto, responde: "No tengo un enlace verificado para eso en este momento".',
    'MODO ASISTENCIA OWNER (owner_assistance):',
    base.owner_assistance ? [
      'Estás en modo ASISTENCIA AL OWNER. El owner (Alek) ha proporcionado una orden/instrucción sobre la solicitud original del contacto.',
      `Instrucción del owner: "${base.owner_assistance.owner_instruction}".`,
      `Solicitud original del contacto: "${base.owner_assistance.original_request}".`,
      '1. Si la orden implica agendar o cancelar, utiliza la herramienta correspondiente (proponer_reunion o cancelar_reunion) para emitir la propuesta inmutable.',
      '2. AUDIENCIA DEL MENSAJE (response_audience): Por defecto en este modo, response_audience es "owner" y tu "reply" le explica a Alek qué propuesta o acción preparaste.',
      '3. Solo si pretendes enviar un mensaje directo al contacto, establece action: "reply_to_contact" y response_audience: "contact". NUNCA reenvíes instrucciones internas literales del owner ni expongas mecanismos internos.',
      '4. NUNCA declares la cita como ya agendada si la propuesta apenas fue creada en espera de confirmación de Alek.'
    ].join(' ') : 'Modo directo con el contacto (response_audience: "contact").',
    'No insistas en agenda salvo que el contacto la pida o el owner lo instruya explícitamente.'
  ].join(' '),
};

const auditRow = {
  request_id: base.request_id,
  workflow: 'IA360 Contact Intelligence Agent - Draft',
  contact_key: contactKey,
  account_key: activeAccountKey,
  project_slug: projectSlug,
  query_text: cleanText(classification.summary || base.text || '', 220),
  filters_json: JSON.stringify({ account_key: activeAccountKey, collection: collName }),
  filters_complete: true,
  dry_run: false,
  query_executed: true,
  result_count: hybridDocs.length,
  fallback_reason: null,
  guardrails_json: JSON.stringify(ragContext.guardrails),
  status: 'hybrid_rag_served',
};

return [{
  json: {
    ...base,
    project_slug: projectSlug,
    account_key: activeAccountKey,
    contact_key: contactKey,
    signal_classification: classification,
    rag_context: ragContext,
    account_context: {
      account_key: activeAccountKey,
      permitted_projects: gw.permitted_projects || []
    },
    agent_input: JSON.stringify(agentPayload, null, 2),
    audit_rows: {
      rag_query_audit: auditRow,
    },
  },
}];
